import { useState } from "react";
import { Mail, Check } from "lucide-react";

function ProfilePage() {
  const [fullName, setFullName] = useState("Krisha Shah");
  const [initials, setInitials] = useState("KS");
  const [saved, setSaved] = useState(false);

  const email = "krisha.shah@example.com";

  const handleSubmit = (e) => {
    e.preventDefault();
    // TODO: send fullName and initials to your backend here
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  };

  const labelClass =
    "block font-mono text-xs tracking-widest uppercase text-slate-500 mb-3";
  const inputClass =
    "w-full rounded-2xl border border-slate-200 bg-white px-5 py-4 text-lg text-ink outline-none transition focus:border-brand focus:ring-4 focus:ring-brand/15";

  return (
    <div className="min-w-[900px] px-14 py-10">
      <div className="max-w-6xl mx-auto">
        {/* Heading */}
        <p className="font-mono text-xs tracking-widest uppercase text-brand">
          Your account
        </p>
        <h1 className="mt-3 text-6xl font-bold tracking-tight">Profile</h1>
        <p className="mt-4 text-lg text-slate-500">
          The details your college friends see when a payment is due.
        </p>

        <div className="mt-12 grid grid-cols-[1fr_1.8fr] gap-8">
          {/* Summary card */}
          <div className="rounded-[2rem] bg-white border border-slate-200 px-10 py-12 flex flex-col items-center justify-center text-center">
            <div className="w-28 h-28 rounded-full bg-brand ring-4 ring-white shadow-md flex items-center justify-center text-3xl font-bold text-ink">
              {initials || "?"}
            </div>
            <h2 className="mt-8 text-3xl font-bold tracking-tight">
              {fullName || "Your name"}
            </h2>
            <p className="mt-2 text-lg text-slate-500">
              Student project account
            </p>

            <div className="mt-10 w-full border-t border-amber-100 pt-8 grid grid-cols-[1fr_auto_1fr] items-center">
              <div>
                <p className="text-4xl font-bold">3</p>
                <p className="mt-1 text-slate-500">groups</p>
              </div>
              <div className="w-px h-14 bg-amber-100" />
              <div>
                <p className="text-4xl font-bold">5</p>
                <p className="mt-1 text-slate-500">expenses</p>
              </div>
            </div>
          </div>

          {/* Details form */}
          <form
            onSubmit={handleSubmit}
            className="rounded-[2rem] bg-white border border-slate-200 p-10"
          >
            <p className="font-mono text-xs tracking-widest uppercase text-brand">
              Personal details
            </p>
            <h2 className="mt-3 text-3xl font-bold tracking-tight">
              How you show up
            </h2>

            <div className="mt-10 space-y-8">
              <div>
                <label htmlFor="fullName" className={labelClass}>
                  Full name
                </label>
                <input
                  id="fullName"
                  type="text"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  className={inputClass}
                />
              </div>

              <div>
                <label htmlFor="initials" className={labelClass}>
                  Initials
                </label>
                <input
                  id="initials"
                  type="text"
                  maxLength={3}
                  value={initials}
                  onChange={(e) => setInitials(e.target.value.toUpperCase())}
                  className={inputClass}
                />
              </div>

              <div>
                <label htmlFor="email" className={labelClass}>
                  Email address
                </label>
                <div className="relative">
                  <Mail
                    size={20}
                    className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500"
                  />
                  <input
                    id="email"
                    type="email"
                    value={email}
                    readOnly
                    className="w-full rounded-2xl border border-slate-200 bg-slate-50 pl-14 pr-5 py-4 text-lg text-slate-500 cursor-not-allowed outline-none"
                  />
                </div>
              </div>
            </div>

            <div className="mt-10 flex items-center gap-4">
              <button
                type="submit"
                className="rounded-2xl bg-ink px-8 py-4 text-lg font-semibold text-white hover:bg-inkSoft transition-colors"
              >
                Save changes
              </button>
              {saved && (
                <span className="flex items-center gap-2 font-medium text-money">
                  <Check size={18} />
                  Saved
                </span>
              )}
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

export default ProfilePage;
